<template><div class="app-container ps-page"><h2>知识文档</h2><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false" class="ps-error"/><div class="ps-split"><aside class="ps-panel"><h3>空间范围</h3><el-button link @click="selectSpace()">全部有权空间</el-button><el-tree :data="spaceTree" node-key="id" :props="{label:'name',children:'children'}" highlight-current default-expand-all @node-click="(s:Space)=>selectSpace(s.id)"/></aside><main style="min-width:0"><el-form inline @submit.prevent="load(true)"><el-form-item label="文档名称"><el-input v-model="query.keyword" clearable @keyup.enter="load(true)"/></el-form-item><el-form-item label="上传者"><el-checkbox v-model="query.mine" @change="load(true)">仅本人上传</el-checkbox></el-form-item><el-form-item label="处理状态"><el-select v-model="query.state" clearable><el-option v-for="s in states" :key="s" :label="stateLabel(s)" :value="s"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="load(true)">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><div class="ps-toolbar"><el-button v-hasPermi="['paismart:document:upload']" type="primary" @click="uploadOpen=true">上传文档</el-button><el-button v-hasPermi="['paismart:document:upload']" @click="textOpen=true">新增文本知识</el-button><el-button v-hasPermi="['paismart:search:query']" @click="searchOpen=true">知识检索</el-button><el-button :loading="loading" @click="load()">刷新状态</el-button><el-checkbox v-model="query.deleted" @change="load(true)">查看已删除文档</el-checkbox></div><el-table :data="rows" v-loading="loading" row-key="id"><el-table-column prop="title" label="文档名称" min-width="220" show-overflow-tooltip/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.state==='FAILED'?'danger':'info'">{{stateLabel(row.state)}}</el-tag></template></el-table-column><el-table-column label="大小" width="100"><template #default="{row}">{{row.byteSize===undefined?'—':(row.byteSize/1024/1024).toFixed(2)+' MB'}}</template></el-table-column><el-table-column prop="estimatedTokens" label="预计用量" width="110"/><el-table-column prop="actualTokens" label="实际用量" width="110"/><el-table-column prop="contentVersion" label="内容版本" width="100"/><el-table-column prop="errorMessage" label="失败原因" min-width="140" show-overflow-tooltip/><el-table-column label="操作" width="310" fixed="right"><template #default="{row}"><el-button v-hasPermi="['paismart:document:read']" link type="primary" @click="preview(row)">预览</el-button><template v-if="row.state!=='DELETED'"><el-button v-hasPermi="['paismart:document:reindex']" link @click="act(row,'parse')">解析</el-button><el-button v-hasPermi="['paismart:document:reindex']" link @click="act(row,'vectorization')">向量化</el-button><el-button v-hasPermi="['paismart:document:reindex']" link @click="act(row,'reindex')">重建</el-button><el-button v-if="row.state==='FAILED'" v-hasPermi="['paismart:document:reindex']" link @click="act(row,'retry')">重试</el-button><el-button v-hasPermi="['paismart:document:remove']" link type="danger" @click="remove(row)">删除</el-button></template><el-button v-else v-hasPermi="['paismart:document:remove']" link @click="act(row,'restore')">恢复</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" v-model:page-size="query.pageSize" :total="total" :page-sizes="[20,50,100]" layout="total,sizes,prev,pager,next" @size-change="load(true)" @current-change="load()"/></main></div><UploadDialog v-model="uploadOpen" :spaces="spaces" :initial-space="query.spaceId as Id|undefined" @uploaded="load()" @spaces-changed="loadSpaces"/><DocumentPreview v-model="previewOpen" :document="selected"/><SearchDialog v-model="searchOpen" :space-id="query.spaceId as Id|undefined" @reference="showReference"/><ReferencePreview v-model="referenceOpen" :reference="selectedReference"/><JobDialog v-model="jobOpen" :initial="job" @done="load()"/><el-dialog v-model="textOpen" title="新增文本知识" width="700px"><el-form label-width="100px"><el-form-item label="标题" required><el-input v-model="textForm.title" maxlength="200"/></el-form-item><el-form-item label="所属空间" required><el-select v-model="textForm.spaceId"><el-option v-for="s in spaces" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="可见范围"><el-select v-model="textForm.visibility"><el-option label="仅本人" value="PRIVATE"/><el-option label="所属空间" value="ORGANIZATION"/><el-option label="组织公开" value="PUBLIC"/></el-select></el-form-item><el-form-item label="原文" required><el-input v-model="textForm.body" type="textarea" :rows="12" maxlength="200000" show-word-limit/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="textOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitText">保存知识</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { computed, onMounted, ref, shallowRef } from 'vue'
import { ElMessageBox } from 'element-plus'
import { createText, deleteDocument, documentAction, listDocuments } from '@/api/paismart/documents'
import { listSpaces } from '@/api/paismart/spaces'
import { newKey } from '@/api/paismart/client'
import type { Document, Id, Job, Reference, Space } from '@/types/paismart'
import { errorText, stateLabel, usePage } from '../composables/usePage'
import UploadDialog from './components/UploadDialog.vue'
import DocumentPreview from './components/DocumentPreview.vue'
import SearchDialog from './components/SearchDialog.vue'
import ReferencePreview from '../chat/components/ReferencePreview.vue'
import JobDialog from '../components/JobDialog.vue'
import '../common.css'
const {rows,total,query,loading,error,load}=usePage(listDocuments,{mine:false}),spaces=shallowRef<Space[]>([]),pageError=ref(''),formError=ref(''),saving=ref(false),uploadOpen=ref(false),textOpen=ref(false),searchOpen=ref(false),previewOpen=ref(false),referenceOpen=ref(false),jobOpen=ref(false),selected=shallowRef<Document>(),selectedReference=shallowRef<Reference>(),job=shallowRef<Job>()
const textForm=ref({title:'',body:'',spaceId:undefined as Id|undefined,visibility:'PRIVATE'}),states=['UPLOADED','QUEUED','PARSING','PARSED','INDEXING','READY','FAILED','CANCELED','DELETED']
let textRequest:{fingerprint:string;key:string}|undefined
const spaceTree=computed(()=>{const nodes=spaces.value.map(s=>({...s,children:[] as Space[]}));const map=new Map(nodes.map(s=>[String(s.id),s]));return nodes.filter(s=>{const parent=s.parentId&&map.get(String(s.parentId));if(parent&&parent.id!==s.id){parent.children.push(s);return false}return true})})
function selectSpace(id?:Id){query.value.spaceId=id;void load(true)}
function reset(){query.value={pageNum:1,pageSize:20,mine:false};void load()}
function preview(row:Document){selected.value=row;previewOpen.value=true}
function showReference(reference:Reference){selectedReference.value=reference;referenceOpen.value=true}
async function act(row:Document,action:'parse'|'restore'|'reindex'|'vectorization'|'retry'){pageError.value='';try{const response=await documentAction(row,action);if(response.data?.jobId){job.value={jobId:response.data.jobId,state:response.data.state};jobOpen.value=true}await load()}catch(e){pageError.value=errorText(e)}}
async function remove(row:Document){try{await ElMessageBox.confirm(`删除「${row.title}」后，该文档将退出检索和引用预览；恢复期内可恢复。`, '删除文档',{type:'warning'});await deleteDocument(row);await load()}catch(e){if(e!=='cancel'&&e!=='close')pageError.value=errorText(e)}}
async function submitText(){formError.value='';if(!textForm.value.title.trim()||!textForm.value.body.trim()||!textForm.value.spaceId){formError.value='请填写标题、空间和原文';return}saving.value=true;try{const data={...textForm.value,spaceId:textForm.value.spaceId},fingerprint=JSON.stringify(data);if(textRequest?.fingerprint!==fingerprint)textRequest={fingerprint,key:newKey()};await createText(data,textRequest.key);textOpen.value=false;textForm.value.body='';textForm.value.title='';textRequest=undefined;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function loadSpaces(){try{spaces.value=(await listSpaces()).rows;if(!textForm.value.spaceId)textForm.value.spaceId=spaces.value[0]?.id}catch(e){pageError.value=errorText(e)}}
onMounted(()=>{void load();void loadSpaces()})
</script>
